//! Invoices, and the bank credit that matches them.
//!
//! This is the half of getting paid that no processor is needed for. A customer pushes money to your
//! account; the invoice says what was owed and why; and something has to decide that THIS credit is
//! THAT invoice. Issuing is bookkeeping. The matching is where the judgement lives.
//!
//! # An ambiguous match is reported, never resolved
//!
//! Two invoices to the same client for the same amount are genuinely indistinguishable when a single
//! payment arrives with no reference. Picking the earlier one would be a coin flip wearing a
//! decision's clothes, and the cost lands months later when one is chased that was already paid. So
//! [`match_payments`] returns them as AMBIGUOUS with the competing candidates named, and the only
//! thing that resolves it is a human or a reference number.
//!
//! # Cash basis and accrual basis are different numbers and both are reported
//!
//! What you INVOICED in a period and what you RECEIVED in it are not the same, and which one your
//! tax return wants depends on the basis you file on. Reporting one silently would be picking a tax
//! treatment on somebody's behalf, so [`revenue`] returns both and labels them.
use crate::jurisdiction::{self, Supply, Taxability};
use crate::money::{money, Currency, Money};
use crate::txn::{days_between, Txn};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    /// Written but not sent. Owes nothing and counts toward nothing.
    Draft,
    Issued,
    /// Something arrived, and it was not the whole amount.
    PartlyPaid,
    Paid,
    /// Abandoned deliberately, with a reason. NOT the same as unpaid.
    WrittenOff,
}

impl State {
    pub fn label(self) -> &'static str {
        match self {
            State::Draft => "draft",
            State::Issued => "issued",
            State::PartlyPaid => "partly-paid",
            State::Paid => "paid",
            State::WrittenOff => "written-off",
        }
    }

    /// Whether money is still expected. A draft is not owed and a write-off is not owed.
    pub fn is_outstanding(self) -> bool {
        matches!(self, State::Issued | State::PartlyPaid)
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Invoice {
    /// The reference a payer should quote. THE strongest matching signal there is, which is why it
    /// belongs on the invoice in a form a bank will not mangle.
    pub number: String,
    pub client: String,
    /// `YYYY-MM-DD`.
    pub issued: String,
    pub due: String,
    pub amount: Money,
    pub description: String,
    pub state: State,
    /// Why it was abandoned. Present only for a write-off, and required for one.
    pub write_off_reason: Option<String>,
    /// WHAT was sold. `None` means the invoice does not say — which is not the same as a service,
    /// and is why [`price`] returns undetermined rather than assuming the common case.
    pub supply: Option<Supply>,
    /// WHERE the customer is. Sales tax follows them, not you.
    pub buyer_place: Option<String>,
}

impl Invoice {
    pub fn new(number: &str, client: &str, issued: &str, due: &str, amount: Money, description: &str) -> Invoice {
        Invoice {
            number: number.to_string(),
            client: client.to_string(),
            issued: issued.to_string(),
            due: due.to_string(),
            amount,
            description: description.to_string(),
            state: State::Issued,
            write_off_reason: None,
            supply: None,
            buyer_place: None,
        }
    }

    /// Record what was sold and where it went. Separate from [`Invoice::new`] because an invoice is
    /// legitimately raised before either is settled, and a constructor demanding them would push
    /// callers into passing a placeholder — which is the guess this module exists to avoid.
    pub fn sold(mut self, supply: Supply, buyer_place: Option<&str>) -> Invoice {
        self.supply = Some(supply);
        self.buyer_place = buyer_place.map(str::to_string);
        self
    }
}

/// What tax this invoice carries, or why that cannot be said.
#[derive(Debug, Clone, PartialEq)]
pub enum TaxOutcome {
    Charged { bps: i64, amount: Money, sources: Vec<String> },
    /// Legitimately nothing, WITH the reason — which is what somebody asking wants to see, and what
    /// a bare zero cannot supply.
    None { reason: String, source: String },
    /// Not zero. The difference between "this is exempt" and "nobody recorded enough to say" is the
    /// difference between an invoice you can defend and one you cannot.
    Undetermined { what: String, where_to: String },
}

#[derive(Debug, Clone, PartialEq)]
pub struct Priced {
    pub invoice: String,
    pub net: Money,
    pub tax: TaxOutcome,
    /// `None` when the tax is undetermined. A total you cannot compute must not be printed as if the
    /// tax were zero — that is a number somebody would send to a customer.
    pub total: Option<Money>,
}

/// Price an invoice: net, tax, and a total only when the tax is actually known.
pub fn price(
    inv: &Invoice,
    seller_place: &str,
    rates: &[jurisdiction::Rate],
    places: &[jurisdiction::Place],
    on: &str,
) -> Result<Priced, String> {
    let undetermined = |what: String, where_to: &str| Priced {
        invoice: inv.number.clone(),
        net: inv.amount,
        tax: TaxOutcome::Undetermined { what, where_to: where_to.to_string() },
        total: None,
    };
    let Some(supply) = inv.supply else {
        return Ok(undetermined(
            format!("{} does not record WHAT was sold", inv.number),
            "set it with `bsc fin invoice new … --supply <service|good|digital|saas>` — taxability turns on the kind of supply, so it cannot be inferred from the amount",
        ));
    };
    let t = jurisdiction::taxability_for_sale(rates, places, seller_place, inv.buyer_place.as_deref(), supply, on)?;
    Ok(match t {
        Taxability::Exempt { reason, source } => Priced {
            invoice: inv.number.clone(),
            net: inv.amount,
            tax: TaxOutcome::None { reason: reason.to_string(), source: source.to_string() },
            // Exempt is a KNOWN zero, so the total is the net and is safe to print.
            total: Some(inv.amount),
        },
        Taxability::Taxable { bps, sources } => {
            let amount = jurisdiction::apply_bps(inv.amount, bps);
            Priced {
                invoice: inv.number.clone(),
                net: inv.amount,
                tax: TaxOutcome::Charged { bps, amount, sources: sources.iter().map(|s| (*s).to_string()).collect() },
                total: Some(money(inv.amount.minor + amount.minor, inv.amount.currency)),
            }
        }
        Taxability::Unknown { what_to_check, where_to_check } => undetermined(what_to_check, where_to_check),
    })
}

/// How confident the match is, and therefore whether a human needs to look.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Confidence {
    /// The invoice number appears in the payment description. Nothing beats this.
    Reference,
    /// The amount is exact and only one invoice could be it.
    ExactAmount,
    /// The amount is exact but SEVERAL invoices fit. Reported, not resolved.
    Ambiguous,
}

impl Confidence {
    pub fn label(self) -> &'static str {
        match self {
            Confidence::Reference => "reference",
            Confidence::ExactAmount => "exact-amount",
            Confidence::Ambiguous => "ambiguous",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Matched {
    pub invoice: String,
    pub date: String,
    pub amount: Money,
    pub confidence: Confidence,
    /// What the description actually said, so the match can be checked rather than trusted.
    pub evidence: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Ambiguity {
    pub date: String,
    pub amount: Money,
    pub description: String,
    /// Every invoice this credit could equally be. Naming them IS the output.
    pub candidates: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MatchResult {
    pub matched: Vec<Matched>,
    /// Credits that fit several invoices equally well. A human or a reference resolves these.
    pub ambiguous: Vec<Ambiguity>,
    /// Money that arrived and belongs to no invoice — a refund, a transfer, or an invoice you never
    /// raised. Reported rather than dropped.
    pub unexplained: Vec<Txn>,
    pub notes: Vec<String>,
}

/// Strip everything a bank might mangle, so `INV-2026-014` still matches `INV2026014`.
fn squash(s: &str) -> String {
    s.chars().filter(|c| c.is_alphanumeric()).collect::<String>().to_uppercase()
}

pub struct MatchOptions {
    /// A credit dated more than this many days before an invoice's issue date cannot be its payment.
    /// Small and non-zero because bank value dates drift by a day or two.
    pub grace_days: i64,
}

impl Default for MatchOptions {
    fn default() -> Self {
        MatchOptions { grace_days: 2 }
    }
}

/// Match incoming credits against outstanding invoices.
///
/// Reference first, then exact amount, and each credit claims AT MOST ONE invoice while each invoice
/// is claimed AT MOST ONCE — the same discipline `spending` uses for transfer pairing, and for the
/// same reason: without it two invoices of equal value both match one payment and one gets chased
/// after it was already settled.
pub fn match_payments(invoices: &[Invoice], credits: &[Txn], opts: &MatchOptions) -> MatchResult {
    let mut matched: Vec<Matched> = Vec::new();
    let mut ambiguous: Vec<Ambiguity> = Vec::new();
    let mut unexplained: Vec<Txn> = Vec::new();
    let mut notes: Vec<String> = Vec::new();
    let mut claimed: Vec<String> = Vec::new();

    let open: Vec<&Invoice> = invoices.iter().filter(|i| i.state.is_outstanding()).collect();
    if open.is_empty() && !credits.is_empty() {
        notes.push("no invoice is outstanding, so every credit below is unexplained by construction rather than by failure to match".to_string());
    }

    // TWO PASSES, AND THE ORDER IS THE POINT. Resolving each credit in turn let an amount-only
    // match claim an invoice that a LATER credit named explicitly — measured end to end: an
    // unreferenced 2400.00 took INV-015, and the payment whose description actually said
    // "REF INV-015" was then reported as belonging to no invoice. A reference is strictly stronger
    // evidence than a coinciding amount, so every reference is resolved before any amount is.
    let incoming: Vec<&Txn> = credits.iter().filter(|t| t.amount.minor > 0).collect();
    let mut by_reference: Vec<usize> = Vec::new();

    for (n, t) in incoming.iter().enumerate() {
        let desc = squash(&t.description);
        let plausible = |i: &Invoice| days_between(&i.issued, &t.date) >= -opts.grace_days;
        let hit = open
            .iter()
            .find(|i| !claimed.contains(&i.number) && plausible(i) && !squash(&i.number).is_empty() && desc.contains(&squash(&i.number)));
        if let Some(i) = hit {
            claimed.push(i.number.clone());
            by_reference.push(n);
            matched.push(Matched {
                invoice: i.number.clone(),
                date: t.date.clone(),
                amount: t.amount,
                confidence: Confidence::Reference,
                evidence: t.description.clone(),
            });
        }
    }

    for (n, t) in incoming.iter().enumerate() {
        if by_reference.contains(&n) {
            continue;
        }
        // A credit cannot pay an invoice that did not exist yet. The grace window absorbs bank value
        // dates without opening the door to matching a payment to a later invoice entirely.
        let plausible = |i: &Invoice| days_between(&i.issued, &t.date) >= -opts.grace_days;

        // The exact amount, but only when exactly one invoice could be it.
        let fits: Vec<&&Invoice> = open.iter().filter(|i| !claimed.contains(&i.number) && plausible(i) && i.amount.minor == t.amount.minor).collect();
        match fits.len() {
            1 => {
                let i = fits[0];
                claimed.push(i.number.clone());
                matched.push(Matched {
                    invoice: i.number.clone(),
                    date: t.date.clone(),
                    amount: t.amount,
                    confidence: Confidence::ExactAmount,
                    evidence: t.description.clone(),
                });
            }
            0 => unexplained.push((*t).clone()),
            _ => {
                // GENUINELY INDISTINGUISHABLE. Picking one is a coin flip that costs somebody a
                // chased invoice months later, so the candidates are named and nothing is decided.
                ambiguous.push(Ambiguity {
                    date: t.date.clone(),
                    amount: t.amount,
                    description: t.description.clone(),
                    candidates: fits.iter().map(|i| i.number.clone()).collect(),
                });
            }
        }
    }

    // The two passes produce references first; a reader expects date order, and the pass a match
    // came from is already recorded as its confidence.
    matched.sort_by(|a, b| a.date.cmp(&b.date).then_with(|| a.invoice.cmp(&b.invoice)));

    if !ambiguous.is_empty() {
        notes.push(format!(
            "{} credit(s) fit more than one invoice equally — put the invoice NUMBER on the invoice and ask payers to quote it, and this stops happening",
            ambiguous.len()
        ));
    }
    if !unexplained.is_empty() {
        notes.push(format!("{} credit(s) match no outstanding invoice — a refund, a transfer, or work you never invoiced", unexplained.len()));
    }

    MatchResult { matched, ambiguous, unexplained, notes }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Settlement {
    pub invoice: String,
    pub client: String,
    pub billed: Money,
    pub received: Money,
    /// POSITIVE when money is still owed, NEGATIVE when they overpaid.
    pub outstanding: Money,
    pub state: State,
}

/// Apply matched payments to invoices and say what each one is actually owed.
///
/// A partial payment leaves the invoice PARTLY PAID with the shortfall named, rather than being
/// rounded up to paid — the missing amount is the whole point and it is the thing to chase.
pub fn settle(invoices: &[Invoice], m: &MatchResult, currency: Currency) -> Vec<Settlement> {
    invoices
        .iter()
        .map(|i| {
            let received: i64 = m.matched.iter().filter(|p| p.invoice == i.number).map(|p| p.amount.minor).sum();
            let outstanding = i.amount.minor - received;
            let state = match i.state {
                State::Draft | State::WrittenOff => i.state,
                _ if received == 0 => State::Issued,
                _ if outstanding > 0 => State::PartlyPaid,
                _ => State::Paid,
            };
            Settlement {
                invoice: i.number.clone(),
                client: i.client.clone(),
                billed: i.amount,
                received: money(received, currency),
                outstanding: money(outstanding, currency),
                state,
            }
        })
        .collect()
}

#[derive(Debug, Clone, PartialEq)]
pub struct AgeBucket {
    pub label: &'static str,
    pub invoices: Vec<String>,
    pub total: Money,
}

/// Outstanding money by how long it has been outstanding.
///
/// The buckets are the standard ones because they are what a person chasing money actually uses, and
/// the 90+ bucket is the honest one: an invoice that old is not late, it is a decision somebody has
/// made about you, and it needs a different conversation rather than another reminder.
pub fn age(settlements: &[Settlement], invoices: &[Invoice], as_of: &str, currency: Currency) -> Vec<AgeBucket> {
    let mut buckets: Vec<AgeBucket> = ["current", "1-30", "31-60", "61-90", "90+"]
        .iter()
        .map(|l| AgeBucket { label: l, invoices: Vec::new(), total: money(0, currency) })
        .collect();
    for s in settlements.iter().filter(|s| s.state.is_outstanding() && s.outstanding.minor > 0) {
        let Some(inv) = invoices.iter().find(|i| i.number == s.invoice) else { continue };
        let overdue = days_between(&inv.due, as_of);
        let idx = if overdue <= 0 {
            0
        } else if overdue <= 30 {
            1
        } else if overdue <= 60 {
            2
        } else if overdue <= 90 {
            3
        } else {
            4
        };
        buckets[idx].invoices.push(s.invoice.clone());
        buckets[idx].total = money(buckets[idx].total.minor + s.outstanding.minor, currency);
    }
    buckets
}

#[derive(Debug, Clone, PartialEq)]
pub struct Revenue {
    pub from: String,
    pub to: String,
    /// What was RECEIVED in the window. What a cash-basis return reports.
    pub cash_basis: Money,
    /// What was INVOICED in the window. What an accrual-basis return reports.
    pub accrual_basis: Money,
    pub note: &'static str,
}

/// Revenue on both bases, because they are different numbers and the difference is a tax question.
///
/// Most sole proprietors file cash basis, but this module does not know that about you and picking
/// one silently would be choosing a tax treatment on your behalf. Both are returned, labelled.
pub fn revenue(invoices: &[Invoice], m: &MatchResult, from: &str, to: &str, currency: Currency) -> Revenue {
    let inside = |d: &str| d >= from && d <= to;
    let cash: i64 = m.matched.iter().filter(|p| inside(&p.date)).map(|p| p.amount.minor).sum();
    let accrual: i64 = invoices
        .iter()
        .filter(|i| i.state != State::Draft && i.state != State::WrittenOff && inside(&i.issued))
        .map(|i| i.amount.minor)
        .sum();
    Revenue {
        from: from.to_string(),
        to: to.to_string(),
        cash_basis: money(cash, currency),
        accrual_basis: money(accrual, currency),
        note: "cash basis counts what ARRIVED in the window; accrual counts what was INVOICED in it. Which one your return wants is a question for whoever files it — this reports both rather than choosing.",
    }
}

/// Abandon an invoice deliberately. A reason is REQUIRED, because an unpaid invoice and one you
/// decided to stop chasing are different facts and only one of them is a bad debt.
pub fn write_off(inv: &mut Invoice, reason: &str) -> Result<(), String> {
    if reason.trim().is_empty() {
        return Err("a write-off needs a reason — an invoice nobody decided to abandon is still owed".to_string());
    }
    inv.state = State::WrittenOff;
    inv.write_off_reason = Some(reason.to_string());
    Ok(())
}

/// Parse a state written by a previous run. An unknown one is an ERROR rather than a default,
/// because defaulting an unreadable state to `issued` would resurrect a write-off as money owed.
pub fn parse_state(s: &str) -> Option<State> {
    match s {
        "draft" => Some(State::Draft),
        "issued" => Some(State::Issued),
        "partly-paid" => Some(State::PartlyPaid),
        "paid" => Some(State::Paid),
        "written-off" => Some(State::WrittenOff),
        _ => None,
    }
}

pub fn to_json(i: &Invoice) -> serde_json::Value {
    serde_json::json!({
        "number": i.number,
        "client": i.client,
        "issued": i.issued,
        "due": i.due,
        "amountMinor": i.amount.minor,
        "currency": i.amount.currency.as_str(),
        "description": i.description,
        "state": i.state.label(),
        "writeOffReason": i.write_off_reason,
        "supply": i.supply.map(|s| s.key()),
        "buyerPlace": i.buyer_place,
    })
}

/// The account registry's refusal, MINUS the one key that means the opposite thing here.
///
/// `number` is on that list because on an ACCOUNT it is the account number — the thing that makes a
/// store worth stealing. On an INVOICE it is the reference printed on the document and quoted by the
/// payer, which is the single most useful field in this module. Everything else on the list still
/// applies unchanged, including a `number` nested inside some other object, which is an account
/// number wearing an invoice's field name.
fn forbidden_key(v: &serde_json::Value) -> Option<String> {
    match v {
        serde_json::Value::Object(map) => {
            let rest: serde_json::Map<String, serde_json::Value> =
                map.iter().filter(|(k, _)| !k.eq_ignore_ascii_case("number")).map(|(k, x)| (k.clone(), x.clone())).collect();
            crate::account::forbidden_key(&serde_json::Value::Object(rest))
        }
        other => crate::account::forbidden_key(other),
    }
}

pub fn from_json(v: &serde_json::Value) -> Result<Invoice, String> {
    if let Some(k) = forbidden_key(v) {
        return Err(format!(
            "`{k}` is not something this store will hold. An invoice records WHAT WAS OWED and by whom — never how anyone pays."
        ));
    }
    let s = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    let number = s("number").ok_or_else(|| "an invoice needs a `number` — it is the reference a payer quotes, and the only thing that separates two identical invoices".to_string())?;
    let amount_minor = v
        .get("amountMinor")
        .and_then(serde_json::Value::as_i64)
        .ok_or_else(|| format!("{number}: `amountMinor` is required, in MINOR units — a decimal here would be a float, and money is not"))?;
    let issued = s("issued").ok_or_else(|| format!("{number}: `issued` is required — without it nothing can tell a payment from a coincidence that predates the work"))?;
    let state_raw = s("state").unwrap_or_else(|| "issued".to_string());
    let state = parse_state(&state_raw).ok_or_else(|| format!("{number}: `{state_raw}` is not a state — one of draft, issued, partly-paid, paid, written-off"))?;
    if state == State::WrittenOff && s("writeOffReason").is_none() {
        return Err(format!("{number}: written off with no reason — an invoice nobody decided to abandon is still owed"));
    }
    let currency = match s("currency").as_deref() {
        None | Some("USD") => Currency::USD,
        Some(other) => return Err(format!("{number}: currency `{other}` is not supported yet, and silently treating it as USD would add unlike amounts together")),
    };
    // An unreadable supply is an ERROR, not a silent None: a typo would otherwise turn a taxable
    // invoice into one that merely "does not say", and the two read very differently on a report.
    let supply = match s("supply") {
        None => None,
        Some(raw) => Some(Supply::parse(&raw).ok_or_else(|| format!("{number}: `{raw}` is not a supply kind — one of service, good, digital, saas"))?),
    };
    Ok(Invoice {
        supply,
        buyer_place: s("buyerPlace"),
        client: s("client").unwrap_or_else(|| "unknown".to_string()),
        due: s("due").unwrap_or_else(|| issued.clone()),
        amount: money(amount_minor, currency),
        description: s("description").unwrap_or_default(),
        write_off_reason: s("writeOffReason"),
        number,
        issued,
        state,
    })
}

pub fn all_to_json(invoices: &[Invoice]) -> serde_json::Value {
    serde_json::Value::Array(invoices.iter().map(to_json).collect())
}

/// Read the store, keeping what parses and REPORTING what does not — a row this cannot read is a
/// row somebody is owed money on, so dropping it silently is the one outcome that must not happen.
pub fn all_from_json(v: &serde_json::Value) -> (Vec<Invoice>, Vec<String>) {
    let mut out: Vec<Invoice> = Vec::new();
    let mut rejected = Vec::new();
    for item in v.as_array().map(Vec::as_slice).unwrap_or_default() {
        match from_json(item) {
            Ok(i) => {
                if out.iter().any(|e: &Invoice| e.number == i.number) {
                    // Two rows with one number breaks the thing the number exists to do.
                    rejected.push(format!("{}: appears twice — an invoice number must be unique or a reference cannot resolve it", i.number));
                } else {
                    out.push(i);
                }
            }
            Err(e) => rejected.push(e),
        }
    }
    out.sort_by(|a, b| a.issued.cmp(&b.issued).then_with(|| a.number.cmp(&b.number)));
    (out, rejected)
}

#[cfg(test)]
mod store_tests {
    use super::*;
    use crate::money::usd;

    #[test]
    fn an_unreadable_row_is_reported_and_never_dropped() {
        // A row this cannot parse is a row somebody OWES you on. Silently skipping it would
        // subtract real money from the outstanding total and nothing would say so.
        let v = serde_json::json!([
            { "number": "A", "client": "ACME", "issued": "2026-06-01", "due": "2026-07-01", "amountMinor": 240_000 },
            { "client": "NO NUMBER", "issued": "2026-06-01", "amountMinor": 100_000 },
            { "number": "C", "issued": "2026-06-01", "amountMinor": 100_000, "state": "banana" },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert_eq!(rejected.len(), 2, "both bad rows are NAMED, not skipped");
        assert!(rejected[0].contains("needs a `number`"));
        assert!(rejected[1].contains("is not a state"));
    }

    #[test]
    fn the_store_refuses_to_hold_how_anyone_pays() {
        let ok = |extra: serde_json::Value| {
            let mut v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1 });
            let serde_json::Value::Object(e) = extra else { unreachable!() };
            for (k, x) in e {
                v[k] = x;
            }
            from_json(&v)
        };
        // Every identity key the account registry refuses is refused here too.
        for k in ["accountNumber", "routing", "iban", "ssn", "cvv", "token"] {
            let err = ok(serde_json::json!({ k: "1234" })).unwrap_err();
            assert!(err.contains("never how anyone pays"), "{k} was accepted");
        }
        // EXCEPT the bare `number`, which on an invoice is the reference, not an account.
        assert!(ok(serde_json::json!({})).is_ok());
        // But a `number` nested inside another object is an account number wearing this field's name.
        assert!(ok(serde_json::json!({ "payer": { "number": "4111111111111111" } })).unwrap_err().contains("never how anyone pays"));
    }

    #[test]
    fn a_write_off_with_no_reason_does_not_survive_a_round_trip() {
        // The in-memory guard is `write_off`; this is the same rule at the STORE boundary, where a
        // hand-edited file could otherwise retire a debt with no record of who decided to.
        let v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1, "state": "written-off" });
        assert!(from_json(&v).unwrap_err().contains("still owed"));
    }

    #[test]
    fn two_rows_with_one_number_is_refused_because_the_number_is_the_key() {
        let v = serde_json::json!([
            { "number": "A", "issued": "2026-06-01", "amountMinor": 100 },
            { "number": "A", "issued": "2026-06-02", "amountMinor": 200 },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert!(rejected[0].contains("must be unique"));
    }

    #[test]
    fn an_invoice_survives_a_round_trip_through_the_store() {
        let mut i = Invoice::new("INV-1", "ACME", "2026-06-01", "2026-07-01", usd(240_000), "consulting");
        i.state = State::PartlyPaid;
        let back = from_json(&to_json(&i)).expect("round trip");
        assert_eq!(back, i);
    }

    #[test]
    fn an_unsupported_currency_is_refused_rather_than_read_as_dollars() {
        let v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1, "currency": "EUR" });
        assert!(from_json(&v).unwrap_err().contains("adding unlike amounts") || from_json(&v).unwrap_err().contains("unlike amounts"));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn inv(number: &str, client: &str, issued: &str, due: &str, amount: i64) -> Invoice {
        Invoice::new(number, client, issued, due, usd(amount), "work")
    }

    fn credit(date: &str, description: &str, minor: i64) -> Txn {
        Txn { account: "chk".into(), date: date.into(), description: description.into(), amount: usd(minor) }
    }

    #[test]
    fn a_consulting_invoice_out_of_duluth_carries_no_tax_and_says_why() {
        // THE CASE THIS WAS BUILT FOR. The total is safe to print because exempt is a KNOWN zero.
        let i = inv("INV-1", "ACME", "2026-06-01", "2026-07-01", 240_000).sold(Supply::ProfessionalService, None);
        let p = price(&i, "us/ga/gwinnett/duluth", jurisdiction::RATES, jurisdiction::PLACES, "2026-09-04").expect("seeded");
        assert_eq!(p.net.minor, 240_000);
        assert_eq!(p.total, Some(usd(240_000)), "nothing is added, and the total is still computable");
        match p.tax {
            TaxOutcome::None { ref reason, ref source } => {
                assert!(reason.contains("professional services are not in it"), "{reason}");
                assert!(source.contains("Georgia DOR"), "a zero has to cite something or it cannot be defended: {source}");
            }
            other => panic!("Georgia does not tax professional services: {other:?}"),
        }
    }

    #[test]
    fn an_invoice_that_does_not_say_what_it_sold_has_no_total() {
        // Undetermined is NOT zero, and the absent total is what stops it being sent as if it were.
        let i = inv("INV-1", "ACME", "2026-06-01", "2026-07-01", 240_000);
        let p = price(&i, "us/ga/gwinnett/duluth", jurisdiction::RATES, jurisdiction::PLACES, "2026-09-04").expect("resolvable");
        assert_eq!(p.total, None, "a total that cannot be computed must not print as the net");
        match p.tax {
            TaxOutcome::Undetermined { ref what, ref where_to } => {
                assert!(what.contains("does not record WHAT was sold"), "{what}");
                assert!(where_to.contains("--supply"), "the fix must be pasteable: {where_to}");
            }
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn a_taxable_invoice_adds_the_tax_and_the_total_is_net_plus_tax() {
        let i = inv("INV-1", "ACME", "2026-06-01", "2026-07-01", 240_000).sold(Supply::DigitalProduct, Some("us/ga/gwinnett/duluth"));
        let p = price(&i, "us/ga/gwinnett/duluth", jurisdiction::RATES, jurisdiction::PLACES, "2026-09-04").expect("seeded");
        match p.tax {
            TaxOutcome::Charged { bps, amount, ref sources } => {
                assert_eq!(bps, 600);
                assert_eq!(amount.minor, 14_400, "6% of 2400.00 is 144.00");
                assert!(!sources.is_empty());
            }
            other => panic!("a download is taxable in Georgia: {other:?}"),
        }
        assert_eq!(p.total, Some(usd(254_400)), "2400.00 + 144.00");
    }

    #[test]
    fn a_taxable_invoice_with_no_customer_place_cannot_be_totalled() {
        // The rate follows the customer, so without one there is no rate — not a zero one.
        let i = inv("INV-1", "ACME", "2026-06-01", "2026-07-01", 240_000).sold(Supply::DigitalProduct, None);
        let p = price(&i, "us/ga/gwinnett/duluth", jurisdiction::RATES, jurisdiction::PLACES, "2026-09-04").expect("resolvable");
        assert_eq!(p.total, None);
        assert!(matches!(p.tax, TaxOutcome::Undetermined { .. }), "{:?}", p.tax);
    }

    #[test]
    fn a_supply_that_will_not_parse_is_an_error_rather_than_a_silent_none() {
        // The two render very differently — "not recorded" versus a taxable good — so a typo must
        // not quietly become the former.
        let v = serde_json::json!({ "number": "A", "issued": "2026-06-01", "amountMinor": 1, "supply": "services" });
        assert!(from_json(&v).unwrap_err().contains("is not a supply kind"));
        // And the pair survives a round trip.
        let i = inv("A", "ACME", "2026-06-01", "2026-07-01", 100).sold(Supply::SoftwareAsService, Some("us/ga"));
        assert_eq!(from_json(&to_json(&i)).expect("round trip"), i);
    }

    #[test]
    fn a_quoted_invoice_number_beats_everything_else() {
        // Two invoices, identical amounts, same client — amount alone cannot separate them. The
        // reference does, which is the entire reason to put it on the invoice.
        let invoices = vec![inv("INV-2026-014", "ACME", "2026-06-01", "2026-07-01", 240_000), inv("INV-2026-015", "ACME", "2026-06-02", "2026-07-02", 240_000)];
        let credits = vec![credit("2026-06-20", "ACME CORP PAYMENT INV2026015", 240_000)];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());
        assert_eq!(m.matched.len(), 1);
        assert_eq!(m.matched[0].invoice, "INV-2026-015", "the reference decided it, not the order");
        assert_eq!(m.matched[0].confidence, Confidence::Reference);
        assert!(m.ambiguous.is_empty());
        // Punctuation the bank stripped does not break it: INV-2026-015 found inside INV2026015.
        assert_eq!(squash("INV-2026-015"), "INV2026015");
    }

    #[test]
    fn two_identical_invoices_and_one_payment_stays_ambiguous() {
        // THE CASE THIS MODULE EXISTS FOR. Picking the earlier one is a coin flip, and the cost
        // arrives months later when the wrong one is chased.
        let invoices = vec![inv("INV-014", "ACME", "2026-06-01", "2026-07-01", 240_000), inv("INV-015", "ACME", "2026-06-02", "2026-07-02", 240_000)];
        let credits = vec![credit("2026-06-20", "ACME CORP PAYMENT", 240_000)];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());
        assert!(m.matched.is_empty(), "nothing was decided");
        assert_eq!(m.ambiguous.len(), 1);
        assert_eq!(m.ambiguous[0].candidates, vec!["INV-014", "INV-015"], "both are named — that IS the output");
        assert!(m.notes.iter().any(|n| n.contains("ask payers to quote it")));
    }

    #[test]
    fn a_referenced_credit_wins_the_invoice_over_an_earlier_amount_only_one() {
        // FOUND END TO END, not in a fixture. Two payments of the same amount: an earlier one with
        // no reference, and a later one naming the invoice. Resolving credits in order let the
        // unreferenced one claim it, and the payment that actually said which invoice it was for
        // came back as "belongs to no invoice" — the exact opposite of the evidence.
        let invoices = vec![inv("INV-015", "ACME", "2026-06-02", "2026-07-02", 240_000)];
        let credits = vec![
            credit("2026-06-20", "ACME CORP PAYMENT", 240_000),
            credit("2026-07-05", "ACME CORP PAYMENT REF INV-015", 240_000),
        ];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());
        assert_eq!(m.matched.len(), 1);
        assert_eq!(m.matched[0].confidence, Confidence::Reference);
        assert_eq!(m.matched[0].date, "2026-07-05", "the credit that NAMED the invoice is the one that got it");
        // The other one is still reported — it is real money that arrived.
        assert_eq!(m.unexplained.len(), 1);
        assert_eq!(m.unexplained[0].date, "2026-06-20");
    }

    #[test]
    fn one_credit_claims_one_invoice_and_no_invoice_is_claimed_twice() {
        // Two payments, two invoices of different sizes. Without the claim, the second payment could
        // re-match the first invoice and one would be recorded paid twice.
        let invoices = vec![inv("A", "ACME", "2026-06-01", "2026-07-01", 100_000), inv("B", "ACME", "2026-06-01", "2026-07-01", 200_000)];
        let credits = vec![credit("2026-06-10", "ACME", 100_000), credit("2026-06-11", "ACME", 100_000)];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());
        assert_eq!(m.matched.len(), 1, "only one invoice was for 1000.00");
        assert_eq!(m.matched[0].invoice, "A");
        // The second identical credit belongs to nothing and is REPORTED rather than dropped.
        assert_eq!(m.unexplained.len(), 1);
    }

    #[test]
    fn a_credit_cannot_pay_an_invoice_that_did_not_exist_yet() {
        let invoices = vec![inv("A", "ACME", "2026-06-10", "2026-07-10", 100_000)];
        // Paid three weeks before it was raised — it is somebody else's money, not this invoice's.
        let early = vec![credit("2026-05-20", "ACME", 100_000)];
        assert!(match_payments(&invoices, &early, &MatchOptions::default()).matched.is_empty());
        // But a day or two of bank value-date drift is absorbed rather than treated as impossible.
        let drift = vec![credit("2026-06-09", "ACME", 100_000)];
        assert_eq!(match_payments(&invoices, &drift, &MatchOptions::default()).matched.len(), 1);
    }

    #[test]
    fn a_partial_payment_leaves_the_shortfall_named_rather_than_rounding_up_to_paid() {
        let invoices = vec![inv("A", "ACME", "2026-06-01", "2026-07-01", 240_000)];
        let credits = vec![credit("2026-06-20", "ACME PAYMENT A", 200_000)];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());
        let s = settle(&invoices, &m, Currency::USD);
        assert_eq!(s[0].state, State::PartlyPaid);
        assert_eq!(s[0].received.minor, 200_000);
        assert_eq!(s[0].outstanding.minor, 40_000, "the missing 400.00 is the thing to chase");
        assert!(s[0].state.is_outstanding());
    }

    #[test]
    fn an_overpayment_shows_as_a_negative_outstanding_rather_than_being_hidden() {
        let invoices = vec![inv("A", "ACME", "2026-06-01", "2026-07-01", 200_000)];
        let credits = vec![credit("2026-06-20", "PAYMENT FOR A", 240_000)];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());
        let s = settle(&invoices, &m, Currency::USD);
        assert_eq!(s[0].state, State::Paid);
        assert_eq!(s[0].outstanding.minor, -40_000, "they overpaid by 400.00 and you owe it back");
        assert!(!s[0].state.is_outstanding());
    }

    #[test]
    fn a_draft_owes_nothing_and_a_write_off_needs_a_reason() {
        let mut d = inv("D", "ACME", "2026-06-01", "2026-07-01", 500_000);
        d.state = State::Draft;
        assert!(!d.state.is_outstanding(), "an unsent invoice is not money owed");
        // A draft is not matchable either — you cannot be paid for something never sent.
        let m = match_payments(&[d.clone()], &[credit("2026-06-20", "ACME", 500_000)], &MatchOptions::default());
        assert!(m.matched.is_empty());
        assert_eq!(m.unexplained.len(), 1);

        let mut w = inv("W", "ACME", "2026-01-01", "2026-02-01", 100_000);
        assert_eq!(write_off(&mut w, "   ").unwrap_err(), "a write-off needs a reason — an invoice nobody decided to abandon is still owed");
        write_off(&mut w, "client dissolved, no recoverable entity").expect("a reason was given");
        assert_eq!(w.state, State::WrittenOff);
        assert!(!w.state.is_outstanding(), "abandoned deliberately is not the same as unpaid");
        assert!(w.write_off_reason.is_some());
    }

    #[test]
    fn ageing_puts_the_ninety_day_bucket_where_it_belongs() {
        let invoices = vec![
            inv("CUR", "A", "2026-06-01", "2026-08-01", 10_000),
            inv("D20", "B", "2026-05-01", "2026-06-20", 20_000),
            inv("D45", "C", "2026-04-01", "2026-05-26", 30_000),
            inv("D75", "D", "2026-03-01", "2026-04-26", 40_000),
            inv("OLD", "E", "2026-01-01", "2026-02-01", 50_000),
        ];
        let m = MatchResult { matched: vec![], ambiguous: vec![], unexplained: vec![], notes: vec![] };
        let s = settle(&invoices, &m, Currency::USD);
        let b = age(&s, &invoices, "2026-07-10", Currency::USD);
        assert_eq!(b[0].invoices, vec!["CUR"], "not yet due");
        assert_eq!(b[1].invoices, vec!["D20"]);
        assert_eq!(b[2].invoices, vec!["D45"]);
        assert_eq!(b[3].invoices, vec!["D75"]);
        assert_eq!(b[4].invoices, vec!["OLD"], "over 90 days — a decision, not a delay");
        assert_eq!(b[4].total.minor, 50_000);
        // A PAID invoice ages into nothing.
        let paid = match_payments(&invoices, &[credit("2026-06-05", "REF CUR", 10_000)], &MatchOptions::default());
        let s2 = settle(&invoices, &paid, Currency::USD);
        assert!(age(&s2, &invoices, "2026-07-10", Currency::USD)[0].invoices.is_empty());
    }

    #[test]
    fn cash_and_accrual_are_different_numbers_and_both_are_reported() {
        // Invoiced in June, paid in July. A cash-basis return counts it in July; an accrual-basis
        // one counts it in June. Reporting one silently would be choosing a tax treatment.
        let invoices = vec![inv("A", "ACME", "2026-06-15", "2026-07-15", 240_000)];
        let credits = vec![credit("2026-07-05", "PAYMENT A", 240_000)];
        let m = match_payments(&invoices, &credits, &MatchOptions::default());

        let june = revenue(&invoices, &m, "2026-06-01", "2026-06-30", Currency::USD);
        assert_eq!(june.accrual_basis.minor, 240_000, "invoiced in June");
        assert_eq!(june.cash_basis.minor, 0, "but nothing arrived in June");

        let july = revenue(&invoices, &m, "2026-07-01", "2026-07-31", Currency::USD);
        assert_eq!(july.cash_basis.minor, 240_000, "it arrived in July");
        assert_eq!(july.accrual_basis.minor, 0);
        assert!(july.note.contains("this reports both rather than choosing"));
    }

    #[test]
    fn a_draft_counts_toward_neither_basis() {
        let mut d = inv("D", "ACME", "2026-06-15", "2026-07-15", 500_000);
        d.state = State::Draft;
        let m = MatchResult { matched: vec![], ambiguous: vec![], unexplained: vec![], notes: vec![] };
        let r = revenue(&[d], &m, "2026-06-01", "2026-06-30", Currency::USD);
        assert_eq!(r.accrual_basis.minor, 0, "an unsent invoice is not revenue on any basis");
    }

    #[test]
    fn money_arriving_against_no_invoice_is_reported_rather_than_absorbed() {
        let m = match_payments(&[], &[credit("2026-06-20", "MYSTERY DEPOSIT", 500_000)], &MatchOptions::default());
        assert_eq!(m.unexplained.len(), 1);
        assert!(m.notes.iter().any(|n| n.contains("unexplained by construction")));
        // And outgoing money is not a payment TO you at all.
        let out = match_payments(&[], &[credit("2026-06-20", "RENT", -120_000)], &MatchOptions::default());
        assert!(out.unexplained.is_empty(), "a debit is not an unmatched receipt");
    }
